#!/bin/bash
# R23-64 sweep driver: 3 arms (t48 control / t64 / t96) x N rounds, interleaved in ROTATED order, each
# launch a fresh server (session.sh). Optional 4th arm: t48 masked to cpus 0-47 (--masked-arm).
#
# Order is generated by sweep_lib.py (round 1: 48 64 96 | round 2: 64 96 48 | round 3: 96 48 64 | repeat),
# never blocked by arm, so no arm owns a fixed slot and slow host drift cannot pose as an arm effect.
# UNIT = LAUNCH. This driver only RUNS launches; analyze_sweep.py is what turns them into a verdict.
#
# RESUMABLE: a launch whose <label>.rows.jsonl exists is skipped (client.py writes it only when the
# launch is complete). A launch that failed twice (<label>.fail2) is skipped so one bad label cannot
# block the rest; it shows up in the analysis as missing. More rounds are added by re-invoking with a
# larger --rounds (the rotation continues), which is also how a screen-DROPPED launch is replaced.
#
#  usage: run_sweep.sh [--rounds 6] [--masked-arm] [--dry-run]
#  env (required): CHAMP=<build>/bin   OUT=<runs dir>
#  env (optional): everything session.sh reads, plus
#     PRE_LAUNCH_CMD   run before EACH server load; rc != 0 stops the driver with rc 6 (e.g. ram_admit.sh 92)
#     FILLER_STOPFILE  honoured between launches (a started launch is finished)
#     FILLER_DEADLINE  epoch: no launch starts unless LAUNCH_NEED_S remain before it
#     FILLER_END       epoch hard end: passed to session.sh as HARD_STOP_EPOCH (server killed by captured pid)
#     LAUNCH_NEED_S=300  seconds a launch needs to start (estimate + margin)
#  exit: 0 all launches present OR window exhausted / stop file (resumable) | 6 PRE_LAUNCH_CMD refused | else session rc
set -uo pipefail
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
CHAMP=${CHAMP:?CHAMP required}; OUT=${OUT:?OUT required}
PY=${PY:-/usr/bin/python3 -E -s}
ROUNDS=6; MASKED=""; DRY=0
while [ $# -gt 0 ]; do
  case $1 in
    --rounds) ROUNDS=$2; shift 2;;
    --masked-arm) MASKED="--masked-arm"; shift;;
    --dry-run) DRY=1; shift;;
    *) echo "unknown arg $1" >&2; exit 64;;
  esac
done
LAUNCH_NEED_S=${LAUNCH_NEED_S:-300}
mkdir -p "$OUT"
ts(){ date -u +%FT%TZ; }
left(){ [ -n "${FILLER_DEADLINE:-}" ] && echo $(( FILLER_DEADLINE - $(date -u +%s) )) || echo 999999; }
[ -n "${FILLER_END:-}" ] && export HARD_STOP_EPOCH=$FILLER_END
export CHAMP OUT

PLAN=$($PY "$HERE/sweep_lib.py" plan --rounds "$ROUNDS" $MASKED) || { echo "$(ts) plan failed"; exit 64; }
total=$(echo "$PLAN" | wc -l); done_n=0
echo "$(ts) R23-64 sweep: $total launches planned (rounds=$ROUNDS${MASKED:+, masked arm}) -> $OUT"
while IFS=$'\t' read -r round label arm threads cpus; do
  if [ -f "$OUT/$label.rows.jsonl" ]; then echo "$(ts) $label done (resume skip)"; done_n=$((done_n+1)); continue; fi
  if [ -f "$OUT/$label.fail2" ]; then echo "$(ts) $label failed twice: skipped (see $OUT/$label.timeline)"; continue; fi
  if [ "$DRY" = 1 ]; then echo "$(ts) [dry-run] would launch $label  -t $threads  taskset -c $cpus"; continue; fi
  [ -n "${FILLER_STOPFILE:-}" ] && [ -e "$FILLER_STOPFILE" ] && { echo "$(ts) stop file: $label not started"; exit 0; }
  l=$(left)
  [ "$l" -lt "$LAUNCH_NEED_S" ] && { echo "$(ts) $label: ${l}s left < ${LAUNCH_NEED_S}s needed: window exhausted, resumes next grant ($done_n/$total done)"; exit 0; }
  if [ -n "${PRE_LAUNCH_CMD:-}" ]; then
    # shellcheck disable=SC2086
    pre=$($PRE_LAUNCH_CMD 2>&1 </dev/null) || { echo "$(ts) $label: PRE_LAUNCH_CMD refused: $pre"; exit 6; }
    echo "$(ts) $label: pre-launch: $pre"
  fi
  echo "$(ts) --- round $round $label  -t $threads  taskset -c $cpus  (${l}s left)"
  bash "$HERE/session.sh" "$label" "$threads" "$cpus" </dev/null; rc=$?
  if [ "$rc" != 0 ]; then
    n=0; [ -f "$OUT/$label.failn" ] && n=$(cat "$OUT/$label.failn"); n=$((n+1)); echo "$n" > "$OUT/$label.failn"
    [ "$n" -ge 2 ] && touch "$OUT/$label.fail2"
    echo "$(ts) ### $label FAILED rc=$rc (failure $n) -- HALTING"; exit "$rc"
  fi
  done_n=$((done_n+1))
done <<< "$PLAN"
echo "$(ts) R23-64 sweep: $done_n/$total launches present"
exit 0
